	 * flag word.
	 */
	from: string;
	/** What replaced it, or null when it was dropped. */
	to: string | null;
	reason: string;
}>;

export type WorkspaceScriptMigration = Readonly<{
	manifest: PackageManifest;
	changes: readonly ScriptFlagChange[];
	unhandled: readonly string[];
}>;

